import React, { useState } from "react";
import TodoList from "./components/TodoList";

export default function App() {
  const [todos, setTodos] = useState([]);
  const [darkMode, setDarkMode] = useState(false);

  const handleAdd = (text) => {
    const trimmed = text.trim();
    if (!trimmed) return;
    setTodos((prev) => [...prev, { id: Date.now(), text: trimmed, done: false }]);
  };

  const handleToggle = (id) => {
    setTodos((prev) =>
      prev.map((todo) => (todo.id === id ? { ...todo, done: !todo.done } : todo))
    );
  };

  const handleRemove = (id) => {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
  };

  const toggleDarkMode = () => setDarkMode((prev) => !prev);

  return (
    <main
      className={
        darkMode
          ? "min-h-screen bg-slate-950 text-slate-100 p-8"
          : "min-h-screen bg-slate-100 text-slate-900 p-8"
      }
    >
      <div className="mx-auto max-w-xl">
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-3xl font-semibold">Todo App</h1>
          <button
            type="button"
            onClick={toggleDarkMode}
            className="rounded-full border border-current px-3 py-1 text-sm"
          >
            {darkMode ? "Light mode" : "Dark mode"}
          </button>
        </div>
        <TodoList
          todos={todos}
          onAdd={handleAdd}
          onToggle={handleToggle}
          onRemove={handleRemove}
        />
      </div>
    </main>
  );
}
